-- Auto-fill learns the real code convention. Most codes are
--   [origin][month][year][audience][type][price][-suffix]
-- e.g. CAJUL25KBPA22 = CA, July, 2025, Kids Boy, Pants, 22 and
-- EOC5BGJE7 = E, October, 2025, Baby Girl, Jeans, 7. The code layout is a
-- regular expression whose named groups split a code into those parts, and
-- "part" rules match on a part (ui/src/utils/productAutofill.js).
--
-- The rules were worked out from the 2,758 codes in the stock-count import
-- (cmd/import_stock_counts/data.go): on the code alone they get the category
-- right for 2,220 and the type for about 2,000. S is Set in codes with a
-- one-digit year (EF6, COC5) and Short in the older two-digit ones (CA22).
ALTER TABLE app_settings
  ADD COLUMN product_autofill_code_layout TEXT NOT NULL DEFAULT '';

UPDATE app_settings SET product_autofill_code_layout = '^(?<origin>[A-Z]+?)(?<month>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|OC|NOV|NV|DEC|DC)?(?<year>\d{1,2})(?<audience>BB|BG|KB|KG|JB|JG|MX|K|B|L|M)?(?<type>[A-Z]+)(?<price>\d+(?:[.,]\d+)?)(?:\D.*)?$'
WHERE id = 1;

